const { AbstractFonts } = await import('../../../abstractFonts.js?ver='+window.srcVersion);
const { Tool } = await import('../../../tool.js?ver='+window.srcVersion);
const { C64ScreenCodes } = await import('./c64ScreenCodes.js?ver='+window.srcVersion);
// begin code

/**
 * The 8x8 character generator ROM of the Commodore 64 (901225-01, 4 KB) as a
 * font: two sets of 256 glyphs, uppercase/graphics first, lowercase/uppercase
 * second, eight bytes a glyph, bit 7 the leftmost pixel — the way the VIC-II
 * reads it. The 4096 bytes are in `fontsData` as 16 rows of 512 hex digits
 * (32 glyphs a row), so a glyph is found by its screen code alone; the second
 * half of each set is the first half inverted, as in the ROM.
 *
 * Two doors into it:
 *
 * - {@link C64Fonts8x8#glyphBytes} gives the eight rows of a **screen code**
 *   in a set — what {@link C64TextRAM} paints a 40x25 screen with, and what a
 *   game copies into a custom character set before it changes a few glyphs.
 * - {@link AbstractFonts#getCharData} makes it a font of the library like
 *   {@link ZXFonts8x8}: a `TextEntity` can print with it anywhere, in either
 *   set (`set` in the constructor), fixed width or proportional.
 *
 * The ROM is Commodore's, now owned by Cloanto; it is here for study of the
 * machine (see SOURCES.md). A game that needs its own character set does
 * not touch this class — it hands `C64TextRAM` an object of its own with
 * `glyphBytes(code, set)`.
 */
export class C64Fonts8x8 extends AbstractFonts {

  /** glyphs in a set */
  static get SET_SIZE() { return 256; }
  /** bytes in a glyph */
  static get GLYPH_BYTES() { return 8; }
  /** glyphs in one row of `fontsData` */
  static get ROW_GLYPHS() { return 32; }

  /**
   * @param {Object} app - The application instance.
   * @param {boolean} [proportional] - Whether glyphs are trimmed to proportional widths.
   * @param {number} [set] - The set `getCharData()` prints in: 0 uppercase/graphics
   *        (the default), 1 lowercase/uppercase.
   */
  constructor(app, proportional, set) {
    super(app);
    this.id = 'C64Fonts8x8';

    this.proportional = !!proportional;
    /** the set text entities print in */
    this.set = set === 1 ? 1 : 0;
    this.charsHeight = 8;
    if (this.proportional) {
      this.charsSpacing = 2;
    }
    this.paragraphSpacing = 8;

    this.monospaceWidth = 8;
    this.spaces = {
      ' ': {width: 5, breaking: true, stretch: true}   // normal (breaking) space; games add hard/short via addSpace()
    };

    /** the ROM: 16 rows of 32 glyphs, 16 hex digits each; rows 0-7 set 0, 8-15 set 1 */
    this.fontsData = [
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      '',
      ''
    ];
    /** glyph rows by set and code, filled on the first request of each */
    this.glyphs = [new Array(C64Fonts8x8.SET_SIZE), new Array(C64Fonts8x8.SET_SIZE)];
  } // constructor

  /**
   * The hex digits of a glyph.
   * @param {number} code - The screen code, 0-255.
   * @param {number} set - 0 or 1.
   * @returns {string} 16 hex digits, top row first.
   */
  glyphHex(code, set) {
    var index = (set === 1 ? C64Fonts8x8.SET_SIZE : 0)+(code & 0xFF);
    var row = Math.floor(index/C64Fonts8x8.ROW_GLYPHS);
    var at = (index%C64Fonts8x8.ROW_GLYPHS)*C64Fonts8x8.GLYPH_BYTES*2;
    return this.fontsData[row].substring(at, at+C64Fonts8x8.GLYPH_BYTES*2);
  } // glyphHex

  /**
   * The eight bytes of a glyph, top row first, bit 7 the leftmost pixel —
   * what the character generator hands the VIC-II. Reverse video codes
   * (128-255) come out inverted, as they are in the ROM. Untrimmed whatever
   * the `proportional` setting, because a cell is always eight pixels wide.
   * @param {number} code - The screen code, 0-255.
   * @param {number} [set] - 0 uppercase/graphics (the default), 1 lowercase/uppercase.
   * @returns {Uint8Array} 8 bytes.
   */
  glyphBytes(code, set) {
    var s = set === 1 ? 1 : 0;
    var c = code & 0xFF;
    if (!this.glyphs[s][c]) {
      var hex = this.glyphHex(c, s);
      var rows = new Uint8Array(C64Fonts8x8.GLYPH_BYTES);
      for (var y = 0; y < C64Fonts8x8.GLYPH_BYTES; y++) {
        rows[y] = parseInt(hex.substring(y*2, y*2+2), 16);
      }
      this.glyphs[s][c] = rows;
    }
    return this.glyphs[s][c];
  } // glyphBytes

  /**
   * A whole set as one block, the 2048 bytes a game copies under $D000 to
   * start a character set of its own from.
   * @param {number} [set] - 0 or 1.
   * @returns {Uint8Array} 2048 bytes, glyph 0 first.
   */
  setBytes(set) {
    var bytes = new Uint8Array(C64Fonts8x8.SET_SIZE*C64Fonts8x8.GLYPH_BYTES);
    for (var code = 0; code < C64Fonts8x8.SET_SIZE; code++) {
      bytes.set(this.glyphBytes(code, set), code*C64Fonts8x8.GLYPH_BYTES);
    }
    return bytes;
  } // setBytes

  /**
   * Decodes a character's glyph into scaled pixel rectangles for the text
   * entities, in the set of this font, trimming blank columns when the font
   * is proportional. Unknown characters fall back to '?'.
   * @param {string} char - The character to render.
   * @param {string} bitMask - The bit value ('1' or '0') treated as a set pixel.
   * @param {number} scale - Pixel scale factor applied to coordinates and sizes.
   * @returns {Object} An object with a data array of [x, y, w, h] rects and the glyph width.
   */
  getCharData(char, bitMask, scale) {
    var spaceData = this.spaceCharData(char, bitMask, scale);
    if (spaceData !== null) {
      return spaceData;
    }

    var width = 8;
    var charObject = {data: []};
    var binData = [];
    var hex = this.glyphHex(C64ScreenCodes.encodeChar(char, this.set), this.set);
    for (var y = 0; y < 8; y++) {
      binData.push(Tool.hexToBin(hex.substring(y*2, y*2+2)));
    }

    if (this.proportional) {
      // left cut
      var doIt = true;
      while (doIt && width > 1) {
        for (var y = 0; y < 8; y++) {
          if (binData[y][0] == bitMask) {
            doIt = false;
            break;
          }
        }
        if (doIt) {
          for (var y = 0; y < 8; y++) {
            binData[y] = binData[y].substring(1);
          }
          width--;
        }
      }
      // right cut
      doIt = true;
      while (doIt && width > 1) {
        for (var y = 0; y < 8; y++) {
          if (binData[y][binData[y].length-1] == bitMask) {
            doIt = false;
            break;
          }
        }
        if (doIt) {
          for (var y = 0; y < 8; y++) {
            binData[y] = binData[y].substring(0, width-1);
          }
          width--;
        }
      }
    }

    binData.forEach((mask, y) => {
      for (var x = 0; x < mask.length; x++) {
        if (mask[x] == bitMask) {
          charObject.data.push([x*scale, y*scale, scale, scale]);
        }
      }
    });
    charObject.width = width*scale;

    return charObject;
  } // getCharData

  /**
   * Reports whether a character has a glyph of its own in the set of this
   * font — one that does not fall back to '?'.
   * @param {string} char - The character to test.
   * @returns {boolean} True if the character is part of the set.
   */
  validChar(char) {
    if (char in this.spaces) {
      return true;
    }
    return char === '?' || C64ScreenCodes.encodeChar(char, this.set) !== 0x3F;
  } // validChar

} // C64Fonts8x8
